<!DOCTYPE html>
<html lang="pt">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?= htmlspecialchars($expedition['reference_code'], ENT_QUOTES, 'UTF-8') ?> | Gestão de Expedientes</title><link rel="stylesheet" href="assets/css/style.css"></head>
<body class="app-page dashboard-layout">
<?php $activePage = 'expedientes'; $pageTitle = 'Expediente'; require __DIR__ . '/partials/app-header.php'; ?>
<main class="content-shell"><?php if ($message): ?><div class="flash <?= htmlspecialchars($message['type'], ENT_QUOTES, 'UTF-8') ?>" role="status"><?= htmlspecialchars($message['message'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><div class="page-heading"><div><p class="section-kicker">Detalhes do expediente</p><h1><?= htmlspecialchars($expedition['reference_code'], ENT_QUOTES, 'UTF-8') ?></h1><p class="muted"><?= htmlspecialchars($expedition['subject'], ENT_QUOTES, 'UTF-8') ?></p></div><span class="state-badge state-<?= htmlspecialchars($expedition['status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars((new ExpeditionController())->getStatuses()[$expedition['status']] ?? $expedition['status'], ENT_QUOTES, 'UTF-8') ?></span></div>
<section class="detail-panel"><dl class="detail-data"><div><dt>Remetente/origem</dt><dd><?= htmlspecialchars($expedition['origin'], ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Destinatário/setor</dt><dd><?= htmlspecialchars($expedition['destination'], ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Data de entrada</dt><dd><?= htmlspecialchars(date('d/m/Y H:i', strtotime($expedition['received_at'])), ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Prioridade</dt><dd><?= htmlspecialchars(['low' => 'Baixa', 'normal' => 'Normal', 'high' => 'Alta', 'urgent' => 'Urgente'][$expedition['priority']] ?? $expedition['priority'], ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Registado por</dt><dd><?= htmlspecialchars($expedition['created_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></dd></div><div><dt>Atualizado por</dt><dd><?= htmlspecialchars($expedition['updated_by_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></dd></div></dl><div class="description-block"><dt>Descrição</dt><p><?= nl2br(htmlspecialchars($expedition['description'] ?: 'Sem descrição.', ENT_QUOTES, 'UTF-8')) ?></p></div></section>
<?php if (hasPermission($connection, 'tramitacoes.view')): ?><a class="primary-link" href="tramitacoes.php?expediente_id=<?= (int) $expedition['id'] ?>">Ver histórico de tramitação</a><?php endif; ?><?php if (hasPermission($connection, 'despachos.view')): ?><a class="primary-link" href="despachos.php?expediente_id=<?= (int) $expedition['id'] ?>">Ver histórico de despachos</a><?php endif; ?><?php if (hasPermission($connection, 'despachos.manage')): ?><a class="primary-link" href="despacho-form.php?expediente_id=<?= (int) $expedition['id'] ?>">Registar despacho</a><?php endif; ?><?php if (hasPermission($connection, 'arquivos.manage') && $expedition['status'] === 'completed'): ?><a class="primary-link" href="arquivo-form.php?expediente_id=<?= (int) $expedition['id'] ?>">Arquivar expediente</a><?php endif; ?><?php if (hasPermission($connection, 'arquivos.view') && $expedition['status'] === 'archived'): ?><a class="primary-link" href="arquivo.php">Ver no arquivo</a><?php endif; ?>
<?php if ($despachos && hasPermission($connection, 'despachos.view')): ?><section class="timeline-panel dispatch-history"><h2>Histórico de despachos</h2><ol class="timeline"><?php foreach ($despachos as $dispatch): ?><li><div class="timeline-marker"></div><div class="timeline-content"><div class="timeline-heading"><strong><?= htmlspecialchars($dispatch['decision'] ?: 'Despacho registado', ENT_QUOTES, 'UTF-8') ?></strong><span><?= htmlspecialchars(date('d/m/Y H:i', strtotime($dispatch['created_at'])), ENT_QUOTES, 'UTF-8') ?></span></div><p><strong>Responsável:</strong> <?= htmlspecialchars($dispatch['author_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></p><p><?= nl2br(htmlspecialchars($dispatch['content'], ENT_QUOTES, 'UTF-8')) ?></p><?php if ($dispatch['observation']): ?><p><strong>Observações:</strong> <?= nl2br(htmlspecialchars($dispatch['observation'], ENT_QUOTES, 'UTF-8')) ?></p><?php endif; ?><span class="state-badge state-dispatch-<?= htmlspecialchars($dispatch['status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars((new DespachoController())->statuses()[$dispatch['status']] ?? $dispatch['status'], ENT_QUOTES, 'UTF-8') ?></span></div></li><?php endforeach; ?></ol></section><?php endif; ?>
<?php if (hasPermission($connection, 'expedientes.manage')): ?><div class="detail-actions"><a class="primary-link" href="expediente-form.php?id=<?= (int) $expedition['id'] ?>">Editar expediente</a><form method="post" action="expediente-status.php"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(getCsrfToken(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $expedition['id'] ?>"><label for="next-status">Alterar estado</label><select id="next-status" name="status"><?php foreach ((new ExpeditionController())->getStatuses() as $key => $label): ?><option value="<?= $key ?>" <?= $expedition['status'] === $key ? 'selected' : '' ?>><?= htmlspecialchars($label, ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select><button type="submit">Atualizar estado</button></form></div><?php endif; ?></main></body></html>